// CSD_RATIONALE_BEGIN
// This strategy follows a two-phase approach: an initial unconstrained phase to explore potential solutions,
// followed by a constrained phase where each token is strictly validated against the problem's grammar.
// During the unconstrained phase, we penalize ">>" to encourage exploring longer chains before encountering "<<".
// In the constrained phase, we use soft constrained sampling to balance exploration and exploitation.
// We also track the number of open "<<" and ">>" tokens to manage the constrained window effectively.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];
var openCount: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    lm.GenerateLogits(prompt + generated);
    helpers.PenalizeTokenLogits(lm, [">>"], 5.0);
    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      openCount := openCount + 1;
    }
  } else {
    if parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      var narrow := helpers.DeadEndDetection(parser, currentConstrained, 2);
      if narrow {
        insideConstrained := false;
      } else {
        var next, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, currentConstrained, 6.0);
        generated := generated + [next];
        steps := steps + 1;
        if isValid {
          currentConstrained := currentConstrained + [next];
          if Contains(next, ">>") { 
            insideConstrained := false;
            openCount := openCount - 1;
          } else if Contains(next, "<<") {
            openCount := openCount + 1;
          }
        } else {
          insideConstrained := false;
        }
      }
    }
  }
}
cost := helpers.cost;

